ValidationRule.errorConditionFormula:
AND( $Profile.Name <> 'System Administrator', TEXT(Type) = 'Complaint',
OR ( AND ( TEXT(Nature_Config__c) <> 'Courier Delivery', TEXT(Nature_Config__c) <> 'Policy Retur', TEXT(Nature_Config__c) <> 'Policy Duplicate', TEXT(Nature_Config__c) <> 'Courier Investigation', Entity__c = 'AMFS', $Profile.Name = 'Other Dept AMFS' ) , Entity__c <> 'AMFS'
) , $Profile.Name <> 'CMU-ALI', $Profile.Name <> 'CMU-AFI', $Profile.Name <> 'CMU A-AMFS', $Profile.Name <> 'CMU B-AMFS', $Profile.Name <> 'CMU C-AMFS', $Profile.Name <> 'CMU D-AMFS', $Profile.Name <> 'CMU-MAGI', $Profile.Name <> 'SPV CMU-AFI', $Profile.Name <> 'SPV CMU-AMFS', $Profile.Name <> 'SPV CMU-MAGI', $Profile.Name <> 'Other Dept MAGI', $Profile.Name <> 'Inbound Agent-MAGI', $Profile.Name <> 'Inbound Agent B-MAGI', $Profile.Name <> 'Outbound Agent MAGI', $Profile.Name <> 'Email Agent-MAGI', $Profile.Name <> 'Walkin Agent-MAGI', OR( ISCHANGED( Progress_Action__c )))
